import {interestPanel} from './debt-interest-view.js?v=20261025e';
import {readPayments,paymentSummary,addPayment,removePayment} from './debt-payments.js?v=20261025e';
import {months,creditors,data,budget,plan,monthTotal} from './debt-core.js?v=20261025e';
const fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:2});
export function debtPage(storage){
 const {entries,error}=readPayments(storage),s=paymentSummary(entries);
 const colors=['#be185d','#6d28d9','#0369a1','#047857','#b45309'];
 const amount=n=>error?'—':fmt(n);
 return `<div class="debt-page">
 <div class="page-heading"><div><span class="eyebrow">พื้นที่ส่วนตัว · แผนปรับปรุง 25 ต.ค. 2569</span><h1>แผนจัดการหนี้</h1><p>ดูยอดผ่อนและติดตามการจ่าย ครบในแอปเรียนเดียวกัน</p></div><a class="button secondary" href="#home">← กลับหน้าการเรียน</a></div>
 <div class="debt-local" role="status"><strong>บันทึกในเครื่องนี้</strong><span>ประวัติการจ่ายสะสมเก็บในเบราว์เซอร์นี้ แยกจากข้อมูลเรียนออนไลน์ และไม่รวมในไฟล์สำรองการเรียน</span></div>
 ${error?`<div class="notice" role="alert">${error}</div>`:''}
 <section class="debt-hero"><div><span class="eyebrow">ยอดหนี้คงเหลือตามฐานแผน</span><p class="debt-balance">${amount(s.left)} <small>บาท</small></p><p>${months[0]}–${months.at(-1)} · ${months.length} เดือน · งบ ${fmt(budget)} บาท/เดือน</p></div><div class="debt-next"><span>งวดแรกที่ยังจ่ายไม่ครบ</span><strong>${error?'ยังอ่านข้อมูลไม่ได้':s.next?`${s.next} · เหลือ ${fmt(s.monthRemaining[s.next])} บาท`:'จ่ายครบตามแผนแล้ว ✓'}</strong><small>รวมยอดจ่ายย่อยของแต่ละเจ้าหนี้จากงวดแรกไปงวดถัดไป</small></div></section>
 <section class="panel debt-entry-panel" aria-labelledby="debt-entry-title"><h2 id="debt-entry-title">บันทึกจ่ายย่อย</h2><p>จ่าย 5, 100 หรือ 1,000 บาทก็สะสมได้ ไม่ต้องรอครบงวด</p><form id="debt-payment-form" class="debt-entry-form"><label>เจ้าหนี้<select id="debt-creditor" required ${error?'disabled':''}><option value="">เลือกเจ้าหนี้</option>${creditors.map(c=>`<option value="${c.key}">${c.name} · เหลือ ${amount(c.balance-s.byCreditor[c.key])} บาท</option>`).join('')}</select></label><label>ยอดจ่ายทั้งหมดครั้งนี้ (บาท)<input id="debt-payment-amount" type="number" inputmode="decimal" min="0.01" step="0.01" required placeholder="เช่น 5 หรือ 1,000" ${error?'disabled':''}></label><label>ในยอดนี้เป็นดอกเบี้ยเพิ่ม (บาท)<input id="debt-payment-interest" type="number" inputmode="decimal" min="0" step="0.01" value="0" required ${error?'disabled':''}></label><button type="submit" class="button primary" ${error?'disabled':''}>บันทึกยอดจ่าย</button></form><p id="debt-payment-error" role="alert" hidden></p><small>กรอกดอกตามใบรับชำระจริง ระบบหักเฉพาะส่วนลดหนี้จากยอดคงเหลือ เช่น จ่าย 100 มีดอก 20 → ลดหนี้ 80 บาท · จ่ายเฉพาะดอกได้ · G และ S ให้ช่องดอกเพิ่มเป็น 0 · ประวัติเก่าคงเป็นยอดลดหนี้ตามที่เคยบันทึก</small></section>
 <section class="debt-stats" aria-label="สรุปแผนหนี้"><div><span>ยอดหนี้ตั้งต้นตามฐานแผน</span><strong>${fmt(s.total)} <small>บาท</small></strong></div><div><span>จ่ายลดหนี้สะสม</span><strong>${amount(s.paid)} <small>บาท</small></strong></div><div><span>งวดที่จ่ายครบ</span><strong>${error?'—':s.count} <small>/ ${months.length} เดือน</small></strong></div></section>
 <section class="panel debt-progress"><div><h2>ความคืบหน้าตามแผน</h2><b>${error?'—':s.percent+'%'}</b></div><progress max="100" ${error?'':`value="${s.percent}"`} aria-label="ความคืบหน้าการจ่าย"></progress><p>จ่ายทุกเจ้าที่ยังมีหนี้ทุกเดือน: G ตามงวดเดิม AEON กันจ่ายสองบัญชีอย่างน้อยบัญชีละ 1,000 บาท สูงกว่าขั้นต่ำในภาพ 378/827 บาท ส่วน LINE, ทอง และ S กันยอดลดหนี้เจ้าละ 1,000 บาท (ถ้าเหลือน้อยกว่านี้ให้จ่ายปิดตามยอดจริง) แล้วใช้เงินที่เหลือเร่งปิด AEON รายการบน → AEON เครดิต → LINE → ทอง → S · เป้ารายเดือนเป็นหลักพัน ยกเว้นงวดปิดและ G แต่ยอดจ่ายจริงแบ่งจ่ายครั้งละเท่าไรก็ได้</p></section>
 <div class="notice debt-assumptions"><strong>แผนลดหนี้ + งวด G ที่รวมดอกแล้ว</strong><p>งบ 15,000 บาท/เดือนใช้จ่ายยอดหนี้ตามฐานแผนและงวด G ยอดที่เหลือจากการปัดเป็นหลักพันไม่ถูกนับว่าจ่ายแล้ว ดอกเบี้ยเพิ่มของ AEON, LINE และทอง P จัดงบแยกต่างหาก เริ่ม ต.ค. 2569 · 8 เดือนจ่ายได้ 120,000 บาท ยังเหลือยอดฐานแผน 13,423.55 บาท จึงต้องใช้อย่างน้อย 9 เดือน แผนประมาณการนี้จบใน 9 เดือนเมื่อจ่ายดอกเพิ่มครบทุกงวดและไม่มีหนี้ใหม่</p><p>งวดสุดท้าย ${months.at(-1)} ใช้ ${fmt(plan.at(-1).total)} บาท เหลืองบ ${fmt(plan.at(-1).unused)} บาท · ประวัติจ่ายเดิมยังคงยอดและเจ้าหนี้เดิม ยอดสะสมจัดเข้าตารางเป้าหมายใหม่นี้</p></div>${interestPanel(storage)}<section class="panel debt-schedule"><div class="section-heading"><div><h2>ตารางลดหนี้และงวด G</h2><p>ดูเป้ารายเดือน ยอดจ่ายสะสม และเงินที่ยังขาด · งวดครบเมื่อสะสมได้ตามเป้าทุกเจ้า</p></div></div><div class="debt-table" tabindex="0" role="region" aria-label="ตารางผ่อนชำระ เลื่อนซ้ายขวาเพื่อดูครบทุกเจ้าหนี้"><table><caption class="sr-only">ตารางจัดสรรงบ 15,000 บาทต่อเดือน ${months[0]} ถึง ${months.at(-1)} หน่วยบาท</caption><thead><tr><th scope="col">เดือน / สถานะ</th>${creditors.map(c=>`<th scope="col">${c.name}</th>`).join('')}<th scope="col">รวม (บาท)</th><th scope="col">งบเหลือ</th></tr></thead><tbody>${months.map(m=>`<tr class="${s.monthRemaining[m]===0?'debt-paid':''}"><th scope="row"><span>${m}</span><small class="debt-month-status">${error?'ยังอ่านยอดไม่ได้':s.monthRemaining[m]===0?'✓ ครบงวด':`ขาด ${fmt(s.monthRemaining[m])} บาท`}</small></th>${creditors.map(c=>{const v=data[m][c.key],last=months.filter(k=>data[k][c.key]>0).at(-1);return `<td>${v?fmt(v):'—'}${c.key==='AEON'&&v?`<small class="debt-cell-paid">รายการบน ${fmt(plan.find(r=>r.month===m).aeonAllocation.aeonUpper)}<br>เครดิต ${fmt(plan.find(r=>r.month===m).aeonAllocation.aeonCard)}</small>`:''}${v?`<small class="debt-cell-paid">สะสม ${amount(s.allocation[m][c.key])}<br>ขาด ${amount(v-s.allocation[m][c.key])}</small>`:''}${v&&last===m?'<small class="debt-close">ปิดตามแผน</small>':''}</td>`;}).join('')}<td><strong>${fmt(monthTotal(m))}</strong><small class="debt-cell-paid">สะสม ${amount(s.monthPaid[m])}</small></td><td>${fmt(budget-monthTotal(m))}</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">รวมทั้งหมด</th>${creditors.map(c=>`<td>${fmt(months.reduce((n,m)=>n+data[m][c.key],0))}</td>`).join('')}<td>${fmt(s.total)}</td><td>${fmt(plan.reduce((n,r)=>n+r.unused,0))}</td></tr></tfoot></table></div><p class="debt-hint">เลื่อนตารางซ้าย–ขวาบนมือถือ · “ปิดตามแผน” คือเดือนสุดท้ายที่จัดสรรเงินครบยอดที่ให้</p></section>
 <section aria-labelledby="debt-creditors-title"><div class="section-heading"><h2 id="debt-creditors-title">แยกตามเจ้าหนี้</h2></div><div class="debt-creditors">${creditors.map((c,i)=>{const total=months.reduce((n,m)=>n+data[m][c.key],0),done=s.byCreditor[c.key];return `<article class="panel" style="--debt-color:${colors[i]}"><h3>${c.name}</h3><p>คงเหลือ <strong>${amount(total-done)} บาท</strong></p><progress max="${total}" ${error?'':`value="${done}"`} aria-label="การจ่าย ${c.name}"></progress><small>จ่ายแล้ว ${amount(done)} / ${fmt(total)} บาท</small></article>`;}).join('')}</div></section>
<section class="panel debt-history" aria-labelledby="debt-history-title"><h2 id="debt-history-title">ประวัติการจ่าย <small>${error?'—':entries.length} รายการ</small></h2><p>จ่ายรวม ${amount(s.cashPaid)} บาท · ลดหนี้ ${amount(s.paid)} บาท · ดอกเพิ่มที่บันทึก ${amount(s.interestPaid)} บาท</p>${error?'<p>ยังอ่านประวัติไม่ได้</p>':entries.length?`<ul>${[...entries].reverse().map(entry=>`<li><div><strong>${entry.creditor} · ${fmt((entry.amountCents+(entry.interestCents||0))/100)} บาท</strong><small>ลดหนี้ ${fmt(entry.amountCents/100)} · ดอกเพิ่ม ${fmt((entry.interestCents||0)/100)} บาท</small><small>${entry.at?new Intl.DateTimeFormat('th-TH',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Bangkok'}).format(new Date(entry.at)):'จากสถานะจ่ายครบที่เคยบันทึก'}</small></div><button class="button secondary small" data-action="debt-remove" data-id="${entry.id}" aria-label="ลบรายการ ${entry.creditor} ${fmt(entry.amountCents/100)} บาท">ลบรายการ</button></li>`).join('')}</ul>`:'<p>ยังไม่มีรายการ เริ่มบันทึกยอดจ่ายย่อยด้านบนได้เลย</p>'}</section>
  </div>`;
}
export function debtAction(action,dataset,storage){if(action==='debt-add')return addPayment(storage,dataset.creditor,dataset.amount,dataset.interest??0);if(action==='debt-remove')return removePayment(storage,dataset.id);return 'ไม่พบคำสั่ง';}
